/**
 * Vercel build bootstrap: pull full source from public GitHub repo.
 * Allows tiny MCP deploys while keeping the real app on GitHub.
 */
import { execSync } from "node:child_process";
import { existsSync, rmSync, mkdirSync, cpSync, readdirSync } from "node:fs";
import { join } from "node:path";

const REPO = "https://codeload.github.com/Julianfam/price-revisit-analyzer/tar.gz/main";

if (existsSync("src/routes/index.tsx") && existsSync("vite.config.ts")) {
  console.log("[bootstrap] source already present — skip");
  process.exit(0);
}

const tmp = "/tmp/pra-src";
rmSync(tmp, { recursive: true, force: true });
mkdirSync(tmp, { recursive: true });

console.log("[bootstrap] downloading", REPO);
execSync(`curl -fsSL "${REPO}" | tar -xz -C "${tmp}" --strip-components=1`, {
  stdio: "inherit",
});

// Copy everything except node_modules / .git / .vercel
const skip = new Set(["node_modules", ".git", ".vercel", ".data"]);
for (const name of readdirSync(tmp)) {
  if (skip.has(name)) continue;
  // Don't overwrite package.json we already installed from
  if (name === "package.json") continue;
  if (name === "package-lock.json") continue;
  const from = join(tmp, name);
  const to = join(process.cwd(), name);
  cpSync(from, to, { recursive: true, force: true });
  console.log("[bootstrap] restored", name);
}

if (!existsSync("src/routes/index.tsx")) {
  console.error("[bootstrap] failed — src missing after extract");
  process.exit(1);
}
console.log("[bootstrap] done");

import type { Plugin } from "vite";
import { defineConfig } from "vite";
import { tanstackStart } from "@tanstack/react-start/plugin/vite";
import viteReact from "@vitejs/plugin-react";
import tailwindcss from "@tailwindcss/vite";
import { nitro } from "nitro/vite";

function pgliteBootstrapPlugin(): Plugin {
  return {
    name: "app-builder:pglite-bootstrap",
    apply: "serve",
    async configureServer(server) {
      try {
        const mod = (await server.ssrLoadModule("/src/lib/db.ts")) as {
          ensureDbReady?: () => Promise<void>;
        };
        if (typeof mod.ensureDbReady === "function") {
          await mod.ensureDbReady();
        }
      } catch (err) {
        console.error("[app-builder] DB bootstrap failed:", err);
        throw err;
      }
    },
  };
}

/**
 * Security headers.
 * Never set X-Frame-Options: SAMEORIGIN — Grok embeds the preview in a
 * cross-origin iframe and Chrome shows "Este contenido está bloqueado".
 */
function securityHeadersPlugin(): Plugin {
  const csp = [
    "default-src 'self'",
    "script-src 'self' 'unsafe-inline' 'unsafe-eval'",
    "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com",
    "font-src 'self' https://fonts.gstatic.com data:",
    "img-src 'self' data: blob: https:",
    "connect-src 'self' https: wss:",
    // Allow Grok product shells + sandbox hosts to embed this app
    "frame-ancestors 'self' https://grok.com https://*.grok.com https://x.ai https://*.x.ai https://*.grok-sandbox.com https://*.grok.me",
    "base-uri 'self'",
    "form-action 'self' https://auth.grok.me https://accounts.google.com https://twitter.com https://x.com https://api.x.com https://*.twitter.com https://*.x.com",
  ].join("; ");

  const apply = (res: {
    setHeader: (k: string, v: string) => void;
    removeHeader: (k: string) => void;
  }) => {
    res.setHeader("X-Content-Type-Options", "nosniff");
    // Drop legacy frame header if a prior middleware set it
    try {
      res.removeHeader("X-Frame-Options");
    } catch {
      /* ignore */
    }
    res.setHeader("Referrer-Policy", "strict-origin-when-cross-origin");
    res.setHeader(
      "Permissions-Policy",
      "camera=(), microphone=(), geolocation=(), payment=()",
    );
    res.setHeader("Content-Security-Policy", csp);
  };

  return {
    name: "app-builder:security-headers",
    configureServer(server) {
      server.middlewares.use((_req, res, next) => {
        apply(res);
        next();
      });
    },
    configurePreviewServer(server) {
      server.middlewares.use((_req, res, next) => {
        apply(res);
        next();
      });
    },
  };
}

function authPopupPlugin(): Plugin {
  return {
    name: "app-builder:auth-popup",
    apply: "serve",
    configureServer(server) {
      server.middlewares.use(async (req, res, next) => {
        try {
          const rawUrl = req.url ?? "";
          const pathOnly = rawUrl.split("?", 1)[0] ?? "";
          if (pathOnly !== "/auth/popup") {
            next();
            return;
          }
          if ((req.method ?? "GET").toUpperCase() === "HEAD") {
            res.statusCode = 200;
            res.setHeader("cache-control", "no-store");
            res.end();
            return;
          }
          if ((req.method ?? "GET").toUpperCase() !== "GET") {
            res.statusCode = 405;
            res.setHeader("content-type", "text/plain; charset=utf-8");
            res.end("Method Not Allowed");
            return;
          }

          const xfHost = String(
            (req.headers["x-forwarded-host"] as string | undefined)
              ?.split(",")[0]
              ?.trim() ?? "",
          );
          const host = String(xfHost || req.headers.host || "localhost:8080");
          const hostName = host.split(":")[0] ?? host;
          const isPublicPreview =
            hostName.endsWith(".grok-sandbox.com") ||
            hostName.endsWith(".grok.me");
          const xfProto = String(
            (req.headers["x-forwarded-proto"] as string | undefined)
              ?.split(",")[0]
              ?.trim() ?? "",
          );
          const proto = String(
            isPublicPreview
              ? "https"
              : xfProto ||
                  ((req.socket as { encrypted?: boolean } | undefined)
                    ?.encrypted
                    ? "https"
                    : "http"),
          );
          const requestHeaders = new Headers();
          for (const [key, value] of Object.entries(req.headers)) {
            if (value === undefined) continue;
            if (Array.isArray(value)) {
              for (const v of value) requestHeaders.append(key, v);
            } else {
              requestHeaders.set(key, value);
            }
          }
          requestHeaders.set("host", host);
          requestHeaders.set("x-forwarded-host", host);
          requestHeaders.set("x-forwarded-proto", proto);

          const request = new Request(`${proto}://${host}${rawUrl}`, {
            method: "GET",
            headers: requestHeaders,
          });

          const mod = (await server.ssrLoadModule(
            "/src/lib/auth/popup.server.ts",
          )) as {
            handleAuthPopupRequest: (req: Request) => Promise<Response>;
          };
          const response = await mod.handleAuthPopupRequest(request);

          res.statusCode = response.status;
          const setCookies =
            typeof response.headers.getSetCookie === "function"
              ? response.headers.getSetCookie()
              : [];
          response.headers.forEach((value, key) => {
            if (key.toLowerCase() === "set-cookie") return;
            // Don't re-apply frame-blocking headers from upstream
            if (key.toLowerCase() === "x-frame-options") return;
            res.setHeader(key, value);
          });
          for (const cookie of setCookies) {
            res.appendHeader("set-cookie", cookie);
          }
          // OAuth bridge: allow any parent + top-level breakout
          try {
            res.removeHeader("X-Frame-Options");
          } catch {
            /* ignore */
          }
          res.setHeader(
            "Content-Security-Policy",
            [
              "default-src 'self'",
              "script-src 'self' 'unsafe-inline'",
              "style-src 'self' 'unsafe-inline'",
              "frame-ancestors *",
              "base-uri 'self'",
              "form-action *",
            ].join("; "),
          );
          const body = Buffer.from(await response.arrayBuffer());
          res.end(body);
        } catch (err) {
          console.error("[app-builder] /auth/popup handler failed:", err);
          if (!res.headersSent) {
            res.statusCode = 500;
            res.setHeader("content-type", "text/plain; charset=utf-8");
            res.end("auth popup failed");
          }
        }
      });
    },
  };
}

export default defineConfig(({ command }) => ({
  server: {
    host: "0.0.0.0",
    port: 8080,
    strictPort: true,
  },
  resolve: { tsconfigPaths: true },
  // Keep PGLite (and its .data / .wasm assets) as a real Node package so
  // import.meta.url resolves under node_modules — never /var/task/_libs.
  ssr: {
    external: ["@electric-sql/pglite", "@electric-sql/pglite-socket"],
  },
  plugins: [
    securityHeadersPlugin(),
    pgliteBootstrapPlugin(),
    authPopupPlugin(),
    tailwindcss(),
    tanstackStart(),
    ...(command === "build" ? [nitro({ preset: "vercel" })] : []),
    viteReact(),
  ],
}));

#!/usr/bin/env node
/**
 * Deploy-time database migrator (node-postgres, `pg`).
 *
 * Runs during `npm run build` — on every Vercel deploy — applying pending files
 * in ../migrations to DATABASE_URL. Each file is applied in one transaction and
 * recorded in a `_migrations` table, so it runs once and is safe to re-run.
 *
 * No DATABASE_URL (local / preview builds) -> skip; the PGLite fallback applies
 * the same files at startup instead (see src/lib/db.ts).
 */
import { readdir, readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import pg from "pg";

const databaseUrl = process.env.DATABASE_URL;
if (!databaseUrl) {
  console.log(
    "[migrate] DATABASE_URL not set — skipping (the PGLite fallback migrates itself).",
  );
  process.exit(0);
}

const migrationsDir = join(dirname(fileURLToPath(import.meta.url)), "..", "migrations");

async function main() {
  const pool = new pg.Pool({ connectionString: databaseUrl, max: 1 });
  const client = await pool.connect();
  try {
    await client.query(
      "CREATE TABLE IF NOT EXISTS _migrations (name TEXT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT now())",
    );
    const applied = new Set(
      (await client.query("SELECT name FROM _migrations")).rows.map((r) => r.name),
    );

    let files;
    try {
      files = (await readdir(migrationsDir)).filter((f) => f.endsWith(".sql")).sort();
    } catch {
      console.log("[migrate] no migrations/ directory — nothing to do.");
      return;
    }

    let count = 0;
    for (const name of files) {
      if (applied.has(name)) continue;
      const text = await readFile(join(migrationsDir, name), "utf8");
      try {
        await client.query("BEGIN");
        // pg's simple-query protocol runs a whole multi-statement file at once.
        await client.query(text);
        await client.query("INSERT INTO _migrations (name) VALUES ($1)", [name]);
        await client.query("COMMIT");
      } catch (err) {
        console.error(`[migrate] error applying ${name}`);
        try {
          await client.query("ROLLBACK");
        } catch {
          // ROLLBACK fails when the connection died — keep the original error.
        }
        throw err;
      }
      console.log(`[migrate] applied ${name}`);
      count += 1;
    }
    console.log(count ? `[migrate] done — ${count} migration(s) applied.` : "[migrate] up to date.");
  } finally {
    client.release();
    await pool.end();
  }
}

main().catch((err) => {
  console.error("[migrate] failed:", err?.message || err);
  // pg errors carry the context needed to debug a bad SQL file.
  for (const key of ["code", "detail", "hint", "position", "where"]) {
    if (err?.[key] != null) console.error(`[migrate]   ${key}: ${err[key]}`);
  }
  process.exit(1);
});

